function Icon({name,size=20,className=''}:{name:keyof typeof icons;size?:number;className?:string}){return <img className={'emp-icon '+className} src={A+icons[name]} alt="" width={size} height={size} draggable={false}/>;}
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateAt=(offset=0)=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+offset);return d;};
const chartDates=Array.from({length:7},(_,i)=>dateAt(i-6));
const chartCrossesMonth=chartDates[0].getMonth()!==dateAt().getMonth();
const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
type Reminder={enabled?:boolean;times:string[];note:string;start:string;end:string;never:boolean;repeat:'daily'|'selected';days:number[]};
const freshReminder=():Reminder=>({times:['08:00','10:00','12:00','14:00','16:00','18:00','20:00'],note:'Drink one glass of water',start:today,end:today,never:true,repeat:'daily',days:[0,2,4]});
const initialLogs=[5,15,5,6,4,5,6];
const ounces=(glasses:number)=>Number((glasses*8).toFixed(1));
function IntakeVolume({value}:{value:number}){return <>{ounces(value)} oz</>;}
function timeLabel(t:string,space=true){const[h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')}${space?' ':''}${h<12?'AM':'PM'}`;}
function dateLabel(t:string){const[y,m,d]=t.split('-');return `${m}/${d}/${y}`;}
function readingDate(i:number){const d=new Date(today+'T12:00:00');d.setDate(d.getDate()-i);return d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}).replace(',','');}
function repeatLabel(r:Reminder){return r.repeat==='daily'||r.days.length===7?'Repeats Everyday':`Repeats ${r.days.map(d=>weekdays[d].slice(0,3)).join(', ')}`;}
function reminderSummary(r:Reminder){
 const repeat=r.repeat==='daily'||r.days.length===7?'daily':r.days.length?`on ${r.days.map(d=>weekdays[d]).join(', ')}`:'on your selected days';
 return `This reminder repeats ${repeat}, starting ${r.start===today?'today':dateLabel(r.start)}${r.never?'':`, until ${dateLabel(r.end)}`}.`;
}
const clamp=(value:number)=>Math.round(Math.max(0,Math.min(1000,Number.isFinite(value)?value:0))*10)/10;
type Store={menuOpen:boolean;setMenuOpen:React.Dispatch<React.SetStateAction<boolean>>;logs:number[];setLogs:React.Dispatch<React.SetStateAction<number[]>>;reminder:Reminder|null;setReminder:React.Dispatch<React.SetStateAction<Reminder|null>>;draft:Reminder;setDraft:React.Dispatch<React.SetStateAction<Reminder>>;notify:(s:string)=>void;reset:()=>void};
const StoreContext=createContext<Store>(null!);const useStore=()=>useContext(StoreContext);
function Counter({value,onChange,label='Glasses consumed'}:{value:number;onChange:(n:number)=>void;label?:string}){
 const keyboard=useKeyboard();const[text,setText]=useState(String(value));useEffect(()=>setText(String(value)),[value]);
 const commit=()=>{const n=clamp(Number(text));setText(String(n));onChange(n);};
 return <div className="intake-counter"><button className="counter-button" aria-label="Decrease glasses" disabled={value<=0} onClick={()=>{keyboard.hide();onChange(clamp(value-1));}}><Icon name="minus" size={24}/></button><KeyboardInput aria-label={label} className="counter-input" inputMode="decimal" value={text} onChange={e=>{const v=e.target.value;if(/^\d*\.?\d?$/.test(v)){setText(v);if(v!==''&&!v.endsWith('.'))onChange(clamp(Number(v)));}}} onBlur={commit} onKeyDown={e=>{if(e.key==='Enter'){commit();keyboard.hide();}}}/><button className="counter-button" aria-label="Increase glasses" disabled={value>=1000} onClick={()=>{keyboard.hide();onChange(clamp(value+1));}}><Icon name="plus" size={32}/></button></div>;
}
function useScrollChrome(){
 const flow=useFlow();
 const [state,setState]=useState({scrolled:false,moreBelow:false});
 useEffect(()=>{
  const scroll=document.querySelector<HTMLElement>('[data-flow-current="true"] .mobile-scroll');
  if(!scroll)return;
  const update=()=>{const next={scrolled:scroll.scrollTop>1,moreBelow:scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop>1};setState(previous=>previous.scrolled===next.scrolled&&previous.moreBelow===next.moreBelow?previous:next);};
  scroll.addEventListener('scroll',update,{passive:true});
  const observer=new ResizeObserver(update);observer.observe(scroll);if(scroll.firstElementChild)observer.observe(scroll.firstElementChild);
  update();
  return()=>{scroll.removeEventListener('scroll',update);observer.disconnect();};
 },[flow.current.key]);
 return state;
}
