function homeReminderClock(){
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());
 const part=(name:string)=>parts.find(p=>p.type===name)!.value;
 return {date:`${part('year')}-${part('month')}-${part('day')}`,time:`${part('hour')}:${part('minute')}`};
}
type MedicationDoseGroup={time:string;mode:'pending'|'taken';date?:string;doseKeys?:string[];home?:boolean};
function HomeReminders(){
 const store=useStore(),meds=useMedications(),hub=useReminderHub(),flow=useFlow();
 const [clock,setClock]=useState(homeReminderClock),[dismissed,setDismissed]=useState<Record<string,boolean>>({});
 const [fluidOpen,setFluidOpen]=useState(false),[medicationGroup,setMedicationGroup]=useState<MedicationDoseGroup|null>(null);
 const [activeId,setActiveId]=useState(''),[cardWidth,setCardWidth]=useState(361),[cardHeight,setCardHeight]=useState(110);
 const wrapper=useRef<HTMLDivElement>(null),activeIdRef=useRef('');
 useEffect(()=>{const timer=window.setInterval(()=>{const next=homeReminderClock();setClock(old=>old.date===next.date&&old.time===next.time?old:next);},1000);return()=>window.clearInterval(timer);},[]);
 const doses=scheduledDoses(meds.medications,clock.date).filter(d=>!dismissed[`medication:${clock.date}:${d.time}`]);
 const medication=selectHomeMedicationReminder(doses,meds.taken,meds.notifications,clock.time);
 const fluidId=`fluid:${clock.date}:${JSON.stringify(store.reminder)}`;
 const dueGeneral=hub.general.filter(g=>ruleRunsOn(g,clock.date)&&g.times.some(t=>t<=clock.time));
 const slides=[...(medication?[{id:`medication:${clock.date}:${medication.time}`,kind:'medication' as const}]:[]),...(store.reminder&&store.reminder.enabled!==false&&!dismissed[fluidId]?[{id:fluidId,kind:'fluid' as const}]:[]),...dueGeneral.map(g=>({id:`general:${g.id}:${clock.date}`,kind:'general' as const,general:g})).filter(g=>!dismissed[g.id])];
 const slideKey=slides.map(s=>s.id).join('\n');
 const selected=Math.max(0,slides.findIndex(s=>s.id===activeId));
 useEffect(()=>{
  const host=wrapper.current,rail=host?.querySelector<HTMLElement>('.home-reminder-rail');
  if(!host||!rail)return;
  const ids=Array.from(host.querySelectorAll<HTMLElement>('.home-reminder-slide')).map(e=>e.dataset.reminderId!);
  let timer=0;
  const update=()=>{const index=Math.max(0,Math.min(ids.length-1,Math.round(rail.scrollLeft/Math.max(1,rail.clientWidth))));const slide=host.querySelectorAll<HTMLElement>('.home-reminder-slide')[index];if(slide){activeIdRef.current=ids[index];setActiveId(ids[index]);}const copies=host.querySelectorAll<HTMLElement>('.home-reminder-copy');setCardHeight(Math.max(110,...Array.from(copies,e=>e.scrollHeight+32)));};
  const align=()=>{setCardWidth(rail.clientWidth);const index=Math.max(0,ids.indexOf(activeIdRef.current));rail.scrollTo({left:index*rail.clientWidth,behavior:'instant'});update();};
  const settle=()=>{window.clearTimeout(timer);timer=window.setTimeout(()=>{if(rail.dataset.dragging==='true')return;const index=Math.round(rail.scrollLeft/Math.max(1,rail.clientWidth));if(Math.abs(rail.scrollLeft-index*rail.clientWidth)>1)rail.scrollTo({left:index*rail.clientWidth,behavior:'smooth'});},140);};
  const onScroll=()=>{update();settle();};
  const gestureObserver=new MutationObserver(()=>{if(rail.dataset.dragging!=='true')settle();});gestureObserver.observe(rail,{attributes:true,attributeFilter:['data-dragging']});
  const observer=new ResizeObserver(()=>{setCardWidth(rail.clientWidth);update();});observer.observe(rail);host.querySelectorAll('.home-reminder-copy').forEach(e=>observer.observe(e));
  rail.addEventListener('scroll',onScroll,{passive:true});align();
  return()=>{observer.disconnect();gestureObserver.disconnect();rail.removeEventListener('scroll',onScroll);window.clearTimeout(timer);};
 },[slideKey]);
 useEffect(()=>{const rail=wrapper.current?.querySelector<HTMLElement>('.home-reminder-rail');if(!rail)return;const index=slides.findIndex(s=>s.id===activeIdRef.current);rail.scrollTo({left:Math.max(0,index)*cardWidth,behavior:'instant'});},[cardWidth]);
 const goTo=(index:number)=>{const target=Math.max(0,Math.min(slides.length-1,index));activeIdRef.current=slides[target].id;setActiveId(slides[target].id);wrapper.current?.querySelector<HTMLElement>('.home-reminder-rail')?.scrollTo({left:target*cardWidth,behavior:'smooth'});};
 if(!slides.length&&!medicationGroup&&!fluidOpen)return null;
 return <>
  {slides.length>0&&<section className="reminder-carousel home-reminders" aria-label="Home reminders" ref={wrapper}>
   <div className="home-reminder-window" style={{height:cardHeight}}>
    <Carousel ariaLabel="Reminder cards" className="home-reminder-rail" contentClassName="home-reminder-track" draggingEnabled={slides.length>1}>
     {slides.map(slide=><article className={'home-reminder-slide home-reminder-'+slide.kind} data-reminder-id={slide.id} key={slide.id} style={{width:cardWidth}} aria-hidden={slide.id!==(slides[selected]?.id)} inert={slide.id!==(slides[selected]?.id)}>
      <img className={"home-reminder-icon "+(slide.kind==='general'?'home-general-icon':'')} src={A+(slide.kind==='general'?'325fc.svg':slide.kind==='medication'?'4b777.svg':'98ae8.svg')} width={slide.kind==='general'?40:slide.kind==='medication'?32:36} height={slide.kind==='general'?40:slide.kind==='medication'?32:36} alt=""/>
      <div className="home-reminder-copy">
       <div className="home-reminder-main">
        <div className="home-reminder-heading"><span className="reminder-tag">{slide.kind==='general'?'General Reminder':slide.kind==='medication'?'Medication Reminder':'Fluid Intake Reminder'}</span><button className="home-reminder-dismiss" aria-label={slide.kind==='general'?'Dismiss general reminder':slide.kind==='medication'?'Dismiss medication reminder':'Dismiss fluid intake reminder'} onClick={()=>setDismissed(old=>({...old,[slide.id]:true}))}><img src={A+'f17c9.svg'} width="13.3333" height="13.3333" alt=""/></button></div>
        {slide.kind==='general'?<strong>{slide.general.note}</strong>:slide.kind==='medication'?<strong>Your {timeLabel(medication!.time)} dose is due</strong>:<button className="home-reminder-fluid-title" aria-label="Open Fluid Intake reminder" onClick={()=>flow.push(detailsScreen)}><strong>{store.reminder!.note}</strong></button>}
       </div>
       {slide.kind==='general'?<button className="log-progress-link" onClick={()=>openHubEditor(flow,hub,store,'general',slide.general)}>View Reminder</button>:slide.kind==='medication'?<button className="log-progress-link" onClick={()=>setMedicationGroup({time:medication!.time,date:clock.date,mode:'pending',doseKeys:medication!.doses.map(d=>d.key),home:true})}>View Medication Details</button>:<button className="log-progress-link" onClick={()=>setFluidOpen(true)}>Log Progress</button>}
      </div>
     </article>)}
    </Carousel>
   </div>
   {slides.length>1&&<div className="banner-pagination" aria-label="Reminder carousel controls"><button className="banner-arrow" aria-label="Previous reminder" disabled={selected===0} onClick={()=>goTo(selected-1)}><img className="flip" src={A+'0af65.svg'} width="6.14286" height="11.1429" alt=""/></button><div className="banner-dots" aria-label={`Reminder ${selected+1} of ${slides.length}`}>{slides.map((slide,index)=><button key={slide.id} className={'banner-dot '+(index===selected?'current':'')} aria-label={`Show ${slide.kind==='general'?'general':slide.kind==='medication'?'medication':'fluid intake'} reminder`} aria-current={index===selected?'true':undefined} onClick={()=>goTo(index)}><img src={A+(index===selected?'795b6.svg':'4a981.svg')} width="6" height="6" alt=""/></button>)}</div><button className="banner-arrow" aria-label="Next reminder" disabled={selected===slides.length-1} onClick={()=>goTo(selected+1)}><img src={A+'0af65.svg'} width="6.14286" height="11.1429" alt=""/></button></div>}
  </section>}
  <HomeProgressSheet open={fluidOpen} onOpenChange={setFluidOpen}/>
  <MedicationDoseSheet group={medicationGroup} onOpenChange={open=>{if(!open)setMedicationGroup(null);}}/>
 </>;
}

